import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:markdeck/sync/engine.dart';

/// Differential engine test: replays every scenario in
/// tool/sync-diff/scenarios/engine_scenarios.json through the Dart port and
/// compares the plan against the fixture the REAL TS engine produced
/// (test/fixtures/engine_cases/*.json, generated by tool/sync-diff/generate.js).
///
/// Any divergence means the Dart port drifted from the TS engine — the CI
/// fixture check (--check) also guards the fixtures against TS-side drift,
/// so a red test here means: fix the Dart port, or regenerate fixtures when
/// the TS engine legitimately changed.
void main() {
  final scenariosFile = File('tool/sync-diff/scenarios/engine_scenarios.json');
  final fixturesDir = Directory('test/fixtures/engine_cases');

  test('scenario file + fixtures exist (run from app/)', () {
    expect(scenariosFile.existsSync(), isTrue, reason: 'cwd must be app/');
    expect(fixturesDir.existsSync(), isTrue);
  });

  final scenarios =
      (jsonDecode(scenariosFile.readAsStringSync()) as List).cast<Map<String, dynamic>>();

  for (final scenario in scenarios) {
    final name = scenario['name'] as String;
    test('diff: $name', () {
      final input = PlanInput(
        server: [
          for (final j in (scenario['server'] as List).cast<Map<String, dynamic>>())
            ServerNode.fromJson(j),
        ],
        local: [
          for (final j in (scenario['local'] as List).cast<Map<String, dynamic>>())
            LocalNode(
              id: j['id'] as String,
              parentId: (j['parentId'] as String?) ?? '',
              type: j['type'] as String,
              title: j['title'] as String,
              url: j['url'] as String?,
              index: ((j['index'] as num?) ?? 0).toInt(),
              isOtherRoot: false,
            ),
        ],
        base: _baseFrom(scenario['base'] as Map<String, dynamic>?),
        touch: _touchFrom(scenario['touch'] as Map<String, dynamic>?),
        deviceId: (scenario['deviceId'] as String?) ?? 'dev-1',
        now: ((scenario['now'] as num?) ?? 2000).toInt(),
        othersId: (scenario['othersId'] as String?) ?? 'md-others',
      );
      final plan = planSync(input);

      // load the fixture produced by the TS engine
      final fixtureFile = fixturesDir
          .listSync()
          .whereType<File>()
          .firstWhere(
            (f) =>
                (jsonDecode(f.readAsStringSync()) as Map<String, dynamic>)['scenario'] ==
                name,
            orElse: () => throw StateError('no fixture for "$name" — regenerate fixtures'),
          );
      final fixture =
          jsonDecode(fixtureFile.readAsStringSync()) as Map<String, dynamic>;

      // compare server ops field-by-field
      final expectedOps = (fixture['serverOps'] as List).cast<Map<String, dynamic>>();
      expect(plan.serverOps.length, expectedOps.length,
          reason: 'server op count for "$name"');
      for (var i = 0; i < expectedOps.length; i++) {
        final e = expectedOps[i];
        final a = plan.serverOps[i];
        final wire = a.toJson(input.deviceId);
        // every field the TS engine emitted must be present with the same value
        e.forEach((k, v) {
          expect(wire[k], v, reason: '$name op[$i].$k');
        });
        expect(wire.keys, e.keys, reason: '$name op[$i] field set');
      }

      // compare local ops structurally
      final expectedChrome = (fixture['chromeOps'] as List).cast<Map<String, dynamic>>();
      expect(plan.chromeOps.length, expectedChrome.length,
          reason: 'chrome op count for "$name"');
      for (var i = 0; i < expectedChrome.length; i++) {
        final e = expectedChrome[i];
        final a = plan.chromeOps[i];
        expect(_kind(a), e['kind'], reason: '$name chrome[$i] kind');
        expect(a.serverId, e['serverId'], reason: '$name chrome[$i] serverId');
        if (e['localId'] != null) {
          expect(a.localId, e['localId'], reason: '$name chrome[$i] localId');
        }
        if (e['title'] != null && a is LocalUpdate) {
          expect(a.title, e['title'], reason: '$name chrome[$i] title');
        }
        if (a is LocalCreate) {
          expect(a.index, e['index'], reason: '$name chrome[$i] index');
          expect(a.type, e['type'], reason: '$name chrome[$i] type');
        }
        if (a is LocalMove) {
          expect(a.index, e['index'], reason: '$name chrome[$i] move index');
        }
      }

      // compare stats
      final stats = fixture['stats'] as Map<String, dynamic>;
      expect(plan.stats.adopted, stats['adopted'], reason: '$name adopted');
      expect(plan.stats.pushed, stats['pushed'], reason: '$name pushed');
      expect(plan.stats.planned, stats['planned'], reason: '$name planned');
      expect(plan.stats.positionPushes, stats['positionPushes'], reason: '$name positionPushes');
      expect(plan.stats.chromeCreates, stats['chromeCreates'], reason: '$name chromeCreates');
      expect(plan.stats.chromeUpdates, stats['chromeUpdates'], reason: '$name chromeUpdates');
      expect(plan.stats.chromeRemoves, stats['chromeRemoves'], reason: '$name chromeRemoves');
      expect(plan.stats.chromeMoves, stats['chromeMoves'], reason: '$name chromeMoves');

      // compare the new base binding set
      final expectedBase = fixture['newBase'] as Map<String, dynamic>;
      expect(plan.newBaseEntries.keys.toSet(), expectedBase.keys.toSet(),
          reason: '$name newBase keys');
      expectedBase.forEach((sid, entry) {
        final e = entry as Map<String, dynamic>;
        final bound = plan.newBaseEntries[sid]!;
        expect(bound.localId, e['localId'], reason: '$name newBase[$sid].localId');
        final expectedServer = e['server'] as Map<String, dynamic>;
        expect(bound.server.id, expectedServer['id']);
        expect(bound.server.parentId, expectedServer['parentId']);
        expect(bound.server.title, expectedServer['title']);
        expect(bound.server.position, expectedServer['position']);
        expect(bound.server.revision, expectedServer['revision']);
        expect(bound.server.updatedAt, expectedServer['updatedAt']);
      });
    });
  }
}

String _kind(LocalOp op) => switch (op) {
  LocalCreate() => 'create',
  LocalUpdate() => 'update',
  LocalMove() => 'move',
  _ => 'remove',
};

Base? _baseFrom(Map<String, dynamic>? j) {
  if (j == null) return null;
  final entries = <String, BaseEntry>{};
  (j['entries'] as Map<String, dynamic>).forEach((sid, e) {
    final m = e as Map<String, dynamic>;
    entries[sid] = BaseEntry(
      server: ServerNode.fromJson(m['server'] as Map<String, dynamic>),
      localId: m['localId'] as String?,
    );
  });
  return Base(
    head: ((j['head'] as num?) ?? 0).toInt(),
    othersId: (j['othersId'] as String?) ?? 'md-others',
    entries: entries,
  );
}

TouchJournal _touchFrom(Map<String, dynamic>? j) {
  final t = <String, TouchEntry>{};
  j?.forEach((id, e) {
    final m = e as Map<String, dynamic>;
    t[id] = TouchEntry(
      at: ((m['at'] as num?) ?? 0).toInt(),
      removed: (m['removed'] as bool?) ?? false,
      title: m['title'] as String?,
      url: m['url'] as String?,
      tags: (m['tags'] as List?)?.cast<String>(),
      reordered: (m['reordered'] as bool?) ?? false,
    );
  });
  return t;
}
